                (r+1,c-1),(r+1,c),(r+1,c+1))):
                continue
            # Continue only through contiguous zero cells. The original motif
            # and any rail cells are left unchanged; extension uses the center axes.
            for dr, dc in ((0,1),(0,-1),(1,0),(-1,0)):
                y, x = r+dr, c+dc
                while 0 <= y < h and 0 <= x < w:
                    if grid[y][x] == 0:
                        out[y][x] = 1
                    elif grid[y][x] == 2:
                        # On a 2-line, color the neighboring 2 cells that flank it
                        # when they are part of the same repeated rail.
                        if dr == 0:
                            for yy in (y-1,y+1):
                                if 0 <= yy < h and grid[yy][x] == 2:
                                    out[yy][x] = 1
                        else:
                            for xx in (x-1,x+1):
