                                    out[y][xx] = 1
                        # Continue across separator rails, but do not overwrite them.
                    y += dr
                    x += dc
            # Restore motif exactly as provided.
            for y in range(r-1,r+2):
                for x in range(c-1,c+2):
                    out[y][x] = grid[y][x]
    return out

