            neighbors = [(r-1,c-1),(r-1,c),(r-1,c+1),(r,c-1),(r,c+1),(r+1,c-1),(r+1,c),(r+1,c+1)]
            if not all(grid[y][x] == 3 for y,x in neighbors):
                continue
            for x in range(w):
                if grid[r][x] == 0:
                    out[r][x] = 1
            for y in range(h):
                if grid[y][c] == 0:
                    out[y][c] = 1
            # Crossing modifications occur only on the 2 rails sharing the ray.
            for y in range(h):
                if grid[y][c] == 2:
                    for x in (c-1,c+1):
                        if 0 <= x < w and grid[y][x] == 2:
